<script setup lang="ts">
import { computed, reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth'; import { getApiError } from '../api/http'
const auth = useAuthStore(); const router = useRouter(); const form = reactive({ username: '', email: '', password: '' }); const error = ref(''); const loading = ref(false)
const validationError = computed(() => { if (form.username && (form.username.length < 3 || form.username.length > 30)) return 'Имя должно содержать от 3 до 30 символов.'; if (form.password && form.password.length < 8) return 'Пароль должен содержать не менее 8 символов.'; return '' })
async function submit() { error.value = validationError.value; if (error.value) return; loading.value = true; try { await auth.register(form); await router.replace({ name: 'dashboard' }) } catch (cause) { error.value = getApiError(cause, 'Не удалось создать аккаунт. Попробуйте ещё раз.') } finally { loading.value = false } }
</script>
<template><main class="flex min-h-screen items-center justify-center bg-slate-950 px-4 py-12"><section class="w-full max-w-md rounded-3xl bg-white p-8 shadow-2xl shadow-black/20 sm:p-10"><p class="text-sm font-semibold uppercase tracking-[0.2em] text-indigo-600">Realtime chat</p><h1 class="mt-3 text-3xl font-bold tracking-tight text-slate-900">Создать аккаунт</h1><p class="mt-2 text-sm text-slate-500">Пара деталей — и вы внутри.</p><form class="mt-8 space-y-5" @submit.prevent="submit"><label class="block text-sm font-medium text-slate-700">Имя пользователя<input v-model.trim="form.username" required minlength="3" maxlength="30" autocomplete="username" class="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100" placeholder="От 3 до 30 символов" /></label><label class="block text-sm font-medium text-slate-700">Email<input v-model.trim="form.email" required type="email" autocomplete="email" class="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100" placeholder="you@example.com" /></label><label class="block text-sm font-medium text-slate-700">Пароль<input v-model="form.password" required minlength="8" type="password" autocomplete="new-password" class="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100" placeholder="Не менее 8 символов" /></label><p v-if="validationError" class="text-sm text-amber-700">{{ validationError }}</p><p v-if="error" role="alert" class="rounded-xl bg-rose-50 px-4 py-3 text-sm text-rose-700">{{ error }}</p><button :disabled="loading || Boolean(validationError)" class="w-full rounded-xl bg-indigo-600 px-4 py-3 font-semibold text-white hover:bg-indigo-700 disabled:opacity-60">{{ loading ? 'Создаём…' : 'Зарегистрироваться' }}</button></form><p class="mt-6 text-center text-sm text-slate-500">Уже есть аккаунт? <RouterLink class="font-semibold text-indigo-600" :to="{ name: 'login' }">Войти</RouterLink></p></section></main></template>
